class ErrorBoundary extends Component{constructor(p){super(p);this.state={error:null}}static getDerivedStateFromError(error){return{error}}render(){if(this.state.error)return <main className="fatal"><p className="eyebrow">The forest path tangled.</p><h1>One world could not open.</h1><p>Your clues and archive are safe. Reload the path or enter the text archive directly.</p><div><button onClick={()=>location.reload()}>Reload journey</button><button onClick={()=>location.hash='archive'}>Open archive</button></div></main>;return this.props.children}}
const whispers={home:['A petal knows your name.','The moss moved when you looked away.','A tiny door just unlocked somewhere.'],student:['The moon keeps a second syllabus.','A star awarded itself to you.','The library moth approves.'],artist:['This pigment was mixed from sunset.','A sketch blinked back.','The flowers are painting you too.'],researcher:['The spores are taking notes.','The helix is humming in D minor.','A phage asked to be redesigned.'],builder:['A tiny bug grew wings.','The terminal planted a seed.','A circuit dreamed of rain.'],writer:['A sentence escaped into the roots.','The comma is a secret door.','A character is hiding in the margin.'],heritage:['The loom remembers every hand.','An old word has opened its eyes.','Gold thread points toward home.'],archive:['One scroll smells faintly of petrichor.','The index rearranges itself at midnight.','A footnote has wandered off.'],finale:['Every found thing is finding you too.','The forest has been listening.','Home was inside the question.']};
function FairyCompanion({page}){const [pos,setPos]=useState({x:82,y:68}),[note,setNote]=useState('');useEffect(()=>{const move=e=>setPos(v=>({x:v.x+(e.clientX/innerWidth*100-v.x)*.08,y:v.y+(e.clientY/innerHeight*100-v.y)*.08}));addEventListener('pointermove',move);return()=>removeEventListener('pointermove',move)},[]);function speak(){const a=whispers[page]||whispers.home;setNote(a[Math.floor(Math.random()*a.length)]);setTimeout(()=>setNote(''),2600)}return <div className="fairy-friend" style={{left:`${pos.x}%`,top:`${pos.y}%`}} onClick={speak} title="A curious fairy"><i/><b>✦</b>{note&&<span>{note}</span>}</div>}
function PetalWeather({kind='petal'}){return <div className={`petal-weather ${kind}`} aria-hidden="true">{Array.from({length:18},(_,i)=><i key={i} style={{'--i':i,'--d':`${7+(i%6)}s`}}>{i%3===0?'✦':i%3===1?'❀':'·'}</i>)}</div>}
function SecretObject({type,label,onFind,children}){const [awake,setAwake]=useState(false);return <button aria-label={label} className={`secret-object ${type} ${awake?'awake':''}`} onClick={()=>{setAwake(true);onFind?.()}}><i/>{children||<span>{awake?'✦':'?'}</span>}</button>}
function Toast({text}){return text?<div className="magic-toast">{text}</div>:null}
function ScenePortal({facet,onClue,clueFound}){const [toast,setToast]=useState('');const tell=t=>{setToast(t);setTimeout(()=>setToast(''),2600)};return <section className={`scene-portal scene-${facet.id}`}><PetalWeather kind={facet.id}/><div className="mist m1"/><div className="mist m2"/><div className="scene-title"><span>touch the world</span><strong>{facet.kicker}</strong></div><div className="scene-ground"/><SecretObject type="mushroom" label="Wake the mushroom" onFind={()=>tell(facet.id==='researcher'?'The mycelium drew a neural network beneath your feet.':'The mushroom sneezed stardust.')}><span>♧</span></SecretObject><SecretObject type="lantern" label="Open the lantern" onFind={()=>tell(facet.id==='writer'?'A lost sentence flew out of the lantern.':'The lantern contains a pocket-sized dawn.')}><span>◇</span></SecretObject><SecretObject type="wing" label="Touch the wings" onFind={()=>tell(facet.id==='heritage'?'The wings beat in the rhythm of an old loom.':'The wings remember how to fly without leaving.')}><span>ʚɞ</span></SecretObject><SecretObject type="clue-orb" label="Look inside the hidden glow" onFind={()=>{onClue();tell(`You caught a word: ${facet.clue}`)}}><span>{clueFound?facet.clue:'✧'}</span></SecretObject><div className="scene-creature" onClick={()=>tell(facet.id==='builder'?'404: ordinary world not found.':'A tiny guardian bows to you.')}>{facet.symbol}</div><p className="scene-instruction">Four things here are listening. One carries a word.</p><Toast text={toast}/></section>}

