function classifyActivity(a,chapter){const t=(a.title+' '+a.text).toLowerCase();if(chapter==='student')return a.kind==='student'||a.kind==='info'||a.kind==='life'||/award|school|exam|scholar|course|program|competition|olympiad|education/.test(t);if(chapter==='artist')return /art|paint|agar dress|creative|film|seed ball|design|illustrat|bioart|music|dance/.test(t);if(chapter==='researcher')return a.kind==='research'||/research|laboratory|phage|biology|cancer|genetic|clinical|intern|paper|publication/.test(t);if(chapter==='builder')return a.kind==='project'||/sugarcode|bionet|platform|module|software|startup|founder|entrepreneur|algorithm|model/.test(t);if(chapter==='writer')return a.kind==='writing'||/story|essay|chapter|mother|birth of|spectrum|alchemy|door/.test(t);if(chapter==='heritage')return /assam|tai-ahom|heritage|faa-sin|language|rural|grandmother|community/.test(t);return false}
function ActivityDossier({item,onClose}){return <div className="dossier-shell" role="dialog" aria-modal="true" aria-label={item.title}><button className="dossier-close" onClick={onClose} aria-label="Close activity"><X/></button><p className="eyebrow">{item.source} · embedded activity {item.id}</p><h2>{item.title}</h2><div className="dossier-body">{item.text.split(/\n+/).map((p,i)=><p key={i}>{p}</p>)}</div></div>}

