 builder:{title:'Boot the moss terminal',prompt:'SugarCode begins with access. Connect the system from human intent to usable biology.',choices:['plain-language prompt','model and simulate','export for the lab','hide the method'],sequence:['plain-language prompt','model and simulate','export for the lab'],success:'The terminal grows a new branch instead of printing a receipt.'},
