function ClueTrial({chapter,onSolved,onClose}){const t=clueTrials[chapter], [picked,setPicked]=useState([]),[shake,setShake]=useState(false);if(!t)return null;function choose(v){const next=[...picked,v];const expected=t.sequence[next.length-1];if(v!==expected){setShake(true);setTimeout(()=>setShake(false),450);setPicked([]);return}setPicked(next);if(next.length===t.sequence.length)setTimeout(onSolved,650)}return <div className="trial-backdrop" role="dialog" aria-modal="true" aria-labelledby="trial-title"><section className={`clue-trial ${shake?'shake':''}`}><button className="trial-x" onClick={onClose} aria-label="Close clue puzzle"><X/></button><p className="eyebrow">A world-specific trial · {picked.length}/{t.sequence.length}</p><h2 id="trial-title">{t.title}</h2><p>{t.prompt}</p><div className="trial-progress">{t.sequence.map((_,i)=><i className={i<picked.length?'on':''} key={i}/>)}</div><div className="trial-choices">{t.choices.map(v=><button disabled={picked.includes(v)} onClick={()=>choose(v)} key={v}>{v}</button>)}</div><small>A wrong choice resets the pattern. Every clue can be solved with keyboard or touch.</small></section></div>}


