function Journey({go,found,setFound}){const [chapter,setChapter]=useState(journeyChapters[0]),[progress,setProgress]=useState(0),[tour,setTour]=useState(false),[selected,setSelected]=useState(null),[query,setQuery]=useState(''),[reveal,setReveal]=useState(null),[deckPage,setDeckPage]=useState(0),[trial,setTrial]=useState(null),[visited,setVisited]=useState(()=>JSON.parse(localStorage.getItem('udita-visited')||'[]')),[passport,setPassport]=useState(false),[threads,setThreads]=useState(false),[timeline,setTimeline]=useState(false),[evidence,setEvidence]=useState(false),[curator,setCurator]=useState(false),[weave,setWeave]=useState(false),[garden,setGarden]=useState(false),[cinema,setCinema]=useState(false),[skills,setSkills]=useState(false),[values,setValues]=useState(false),[galaxy,setGalaxy]=useState(false),[integrity,setIntegrity]=useState(false),[diffLab,setDiffLab]=useState(false),[trailComposer,setTrailComposer]=useState(false),[lensStudio,setLensStudio]=useState(false),[claimMatrix,setClaimMatrix]=useState(false),[queryWorkbench,setQueryWorkbench]=useState(false),[stateCapsule,setStateCapsule]=useState(false);useEffect(()=>localStorage.setItem('udita-visited',JSON.stringify(visited)),[visited]);const list=useMemo(()=>activities.filter(a=>classifyActivity(a,chapter.id)),[chapter]);const filtered=useMemo(()=>list.filter(a=>(a.title+' '+a.text).toLowerCase().includes(query.toLowerCase())),[list,query]);useEffect(()=>{const ch=e=>{const c=journeyChapters.find(x=>x.id===e.detail.id);if(c){setChapter(c);setQuery('');setDeckPage(0)}};const pr=e=>setProgress(e.detail.progress);const lm=e=>{const id=e.detail.chapter,c=journeyChapters.find(x=>x.id===id);if(id==='finale')go('finale');else if(c){setChapter(c);setVisited(v=>v.includes(id)?v:[...v,id]);setReveal(id);setTimeout(()=>setReveal(null),1800)}};const ts=e=>setTour(e.detail.tour);addEventListener('world-chapter',ch);addEventListener('world-progress',pr);addEventListener('world-landmark',lm);addEventListener('world-tour-state',ts);return()=>{removeEventListener('world-chapter',ch);removeEventListener('world-progress',pr);removeEventListener('world-landmark',lm);removeEventListener('world-tour-state',ts)}},[go]);function jump(i){window.dispatchEvent(new WheelEvent('wheel',{deltaY:(i/(journeyChapters.length-1)-progress)*2400}));setChapter(journeyChapters[i]);setDeckPage(0)}function collect(){if(chapter.id==='finale')return go('finale');if(found.includes(chapter.id)){setReveal(facets.find(f=>f.id===chapter.id)?.clue);return}setTrial(chapter.id)}function solveTrial(){const id=trial;setFound(x=>x.includes(id)?x:[...x,id]);setTrial(null);setReveal(facets.find(f=>f.id===id)?.clue);setTimeout(()=>setReveal(null),2600)}return <main className="journey"><Suspense fallback={<div className="forest forest-fallback"/>}><Journey3D/></Suspense><div className="journey-hud"><div className="journey-brand"><span>UP</span><div><b>Udita’s enchanted atlas</b><small>scroll · drag · arrow keys</small></div></div><div className="journey-tools"><AmbientSound/><button className="passport-button" onClick={()=>setPassport(true)}>✦ passport</button><button className="threads-button" onClick={()=>setThreads(true)}>⌘ threads</button><button className="timeline-button" onClick={()=>setTimeline(true)}>◷ timeline</button><button className="evidence-button" onClick={()=>setEvidence(true)}>✧ evidence</button><button className="curator-button" onClick={()=>setCurator(true)}>◎ curator</button><button className="weave-button" onClick={()=>setWeave(true)}>⌁ weave</button><button className="garden-button" onClick={()=>setGarden(true)}>⚘ questions</button><button className="cinema-button" onClick={()=>setCinema(true)}>▶ cinema</button><button className="skills-button" onClick={()=>setSkills(true)}>◉ skills</button><button className="values-button" onClick={()=>setValues(true)}>✥ values</button><button className="galaxy-button" onClick={()=>setGalaxy(true)}>● projects</button><button className="integrity-button" onClick={()=>setIntegrity(true)}>✓ sources</button><button className="diff-button" onClick={()=>setDiffLab(true)}>⇄ compare</button><button className="trail-button" onClick={()=>setTrailComposer(true)}>⌁ trail</button><button className="lens-button" onClick={()=>setLensStudio(true)}>◫ lenses</button><button className="claim-button" onClick={()=>setClaimMatrix(true)}>▦ claims</button><button className="query-button" onClick={()=>setQueryWorkbench(true)}>⌕ query</button><button className="state-button" onClick={()=>setStateCapsule(true)}>◌ state</button><button className={tour?'tour active':'tour'} onClick={()=>dispatchEvent(new Event('world-tour-toggle'))}>{tour?'■ Stop tour':'▶ Guided tour'}</button></div></div><aside className="chapter-rail" aria-label="Journey chapters">{journeyChapters.map((c,i)=><button onClick={()=>jump(i)} className={c.id===chapter.id?'active':''} key={c.id}><i/><span>{c.name}</span></button>)}</aside><div className="journey-progress"><i style={{height:`${progress*100}%`}}/></div><section className="location-card"><p className="eyebrow">Now entering · {chapter.hint}</p><h1>{chapter.name}</h1><p>{facets.find(f=>f.id===chapter.id)?.intro||'Every path has brought your six words here.'}</p><div className="location-actions"><button onClick={collect}>{found.includes(chapter.id)?'word collected ✓':'attempt this world’s trial'}</button><button onClick={()=>go(chapter.id==='finale'?'finale':chapter.id)}>open this world ↗</button></div></section>{chapter.id!=='finale'&&<section className="activity-deck"><header><div><span>{list.length} organized activity passages</span><strong>Everything connected to {facets.find(f=>f.id===chapter.id)?.label}</strong></div><label><Search size={15}/><input value={query} onChange={e=>{setQuery(e.target.value);setDeckPage(0)}} placeholder="filter this space"/></label></header><div className="activity-track">{filtered.slice(deckPage*40,deckPage*40+40).map((a,i)=><button key={a.id} onClick={()=>setSelected(a)} style={{'--n':i}}><span>{String(i+1).padStart(2,'0')}</span><strong>{a.title}</strong><small>{a.source}</small><p>{a.text.slice(0,150)}…</p></button>)}</div><footer><span>Showing {filtered.length?deckPage*40+1:0}–{Math.min(filtered.length,deckPage*40+40)} of {filtered.length}. Every passage is paged here; complete verbatim sources remain in Archive.</span><div><button disabled={deckPage===0} onClick={()=>setDeckPage(x=>Math.max(0,x-1))}>← previous 40</button><button disabled={(deckPage+1)*40>=filtered.length} onClick={()=>setDeckPage(x=>x+1)}>next 40 →</button></div></footer></section>}<div className="journey-instructions">Scroll to travel · drag to look · click the glowing structure · ↑↓←→ also work</div>{reveal&&<div className="world-reveal">{reveal.length<15?`WORD FOUND: ${reveal}`:`${chapter.name} awakened`}</div>}{stateCapsule&&<PortfolioStateCapsule onClose={()=>setStateCapsule(false)} onLaunch={id=>{setStateCapsule(false);const launch={threads:setThreads,timeline:setTimeline,evidence:setEvidence,curator:setCurator,weave:setWeave,questions:setGarden,cinema:setCinema,skills:setSkills,values:setValues,projects:setGalaxy,integrity:setIntegrity,diffLab:setDiffLab,trailComposer:setTrailComposer,lensStudio:setLensStudio,claimMatrix:setClaimMatrix,queryWorkbench:setQueryWorkbench}[id];if(launch)launch(true);else if(id==='archive')go('archive')}}/>} {queryWorkbench&&<ArchiveQueryWorkbench onClose={()=>setQueryWorkbench(false)} onOpen={a=>{setQueryWorkbench(false);setSelected(a)}}/>} {claimMatrix&&<ClaimContextMatrix onClose={()=>setClaimMatrix(false)} onOpen={a=>{setClaimMatrix(false);setSelected(a)}}/>} {lensStudio&&<AudienceLensStudio onClose={()=>setLensStudio(false)} onOpen={a=>{setLensStudio(false);setSelected(a)}}/>} {trailComposer&&<NarrativeTrailComposer onClose={()=>setTrailComposer(false)}/>} {diffLab&&<ProvenanceDiffLab onClose={()=>setDiffLab(false)}/>} {integrity&&<IntegrityDesk go={go} onClose={()=>setIntegrity(false)}/>} {galaxy&&<ProjectGalaxy onClose={()=>setGalaxy(false)} onOpen={a=>{setGalaxy(false);setSelected(a)}}/>} {values&&<ValuesCompass onClose={()=>setValues(false)} onOpen={a=>{setValues(false);setSelected(a)}}/>} {skills&&<SkillsObservatory onClose={()=>setSkills(false)} onOpen={a=>{setSkills(false);setSelected(a)}}/>} {cinema&&<ArtifactCinema onClose={()=>setCinema(false)} onOpen={a=>{setCinema(false);setSelected(a)}}/>} {garden&&<QuestionGarden onClose={()=>setGarden(false)} onOpen={a=>{setGarden(false);setSelected(a)}}/>} {weave&&<RelationshipWeave onClose={()=>setWeave(false)} onOpen={a=>{setWeave(false);setSelected(a)}}/>} {curator&&<CuratorMode onClose={()=>setCurator(false)} onOpen={a=>{setCurator(false);setSelected(a)}}/>} {evidence&&<EvidenceConstellation onClose={()=>setEvidence(false)} onOpen={a=>{setEvidence(false);setSelected(a)}}/>} {timeline&&<TimelineObservatory onClose={()=>setTimeline(false)} onOpen={a=>{setTimeline(false);setSelected(a)}}/>} {threads&&<ThreadAtlas onClose={()=>setThreads(false)} onOpen={a=>{setThreads(false);setSelected(a)}}/>} {passport&&<Passport found={found} visited={visited} onClose={()=>setPassport(false)}/>} {trial&&<ClueTrial chapter={trial} onSolved={solveTrial} onClose={()=>setTrial(null)}/>} {selected&&<ActivityDossier item={selected} onClose={()=>setSelected(null)}/>}</main>}
function Nav({page,go,found}){return <nav><button className="brand" onClick={()=>go('home')}><span>UP</span><em>enchanted archive</em></button><div className="navlinks">{facets.map(f=><button key={f.id} className={page===f.id?'active':''} onClick={()=>go(f.id)}>{f.label}</button>)}<button onClick={()=>go('archive')}>Archive</button></div><button className="journey-link" onClick={()=>go('journey')}>3D journey</button><button className="satchel" onClick={()=>go('finale')}><Sparkles size={15}/>{found.length}/6</button></nav>}
function Home({go}){const [toast,setToast]=useState('');const tell=t=>{setToast(t);setTimeout(()=>setToast(''),2600)};return <main className="home wonder-home"><PetalWeather/><div className="canopy"><span/><span/><span/><span/></div><div className="hero-copy"><p className="eyebrow">The forest has been expecting you</p><h1>Udita<br/><i>Phookan</i></h1><p className="lead">Scientist, illustrator, builder and storyteller. Step into a living archive where questions glow, stories have wings, and the path changes when you touch it.</p><button className="primary" onClick={()=>go('journey')}>Enter the 3D journey <ArrowRight size={18}/></button><p className="hint">Six words are concealed inside six different worlds. Nothing labeled “clue” is ever the clue.</p></div><div className="hero-garden"><div className="garden-moon"/><div className="waterfall"/><SecretObject type="home-mushroom" label="A glowing mushroom" onFind={()=>tell('It blushes. Under its cap: “Never trust a silent footnote.”')}><span>♧</span></SecretObject><SecretObject type="home-lantern" label="A hanging lantern" onFind={()=>tell('Three moths escape, spelling U-D-I-T-A for half a second.')}><span>◇</span></SecretObject><SecretObject type="tiny-door" label="A very small door" onFind={()=>tell('The door is too small for you. A note slides out: “Try being curious instead.”')}><span>⌂</span></SecretObject></div><section className="map"><h2>Six worlds are growing here</h2><p>Each has its own weather, rules and hidden life.</p><div className="facet-grid">{facets.map((f,i)=><button onClick={()=>go(f.id)} className={`facet-card ${f.tone}`} key={f.id}><span className="num">0{i+1}</span><f.icon/><strong>{f.label}</strong><small>{f.kicker}</small><em>enter world ↗</em></button>)}</div></section><Toast text={toast}/></main>}
function DocReader({doc,onClose}){const closeRef=useRef(null);useEffect(()=>{const prev=document.activeElement;document.body.classList.add('modal-open');closeRef.current?.focus();const key=e=>e.key==='Escape'&&onClose();addEventListener('keydown',key);return()=>{removeEventListener('keydown',key);document.body.classList.remove('modal-open');prev?.focus?.()}},[onClose]);return <div className="modal" role="dialog" aria-modal="true" aria-labelledby={`doc-title-${doc.id}`} onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="reader"><button ref={closeRef} className="close" aria-label="Close document" onClick={onClose}><X/></button><p className="eyebrow">Source scroll {String(doc.id).padStart(2,'0')}</p><h2 id={`doc-title-${doc.id}`}>{doc.title}</h2><div className="fulltext">{doc.text.split(/\n+/).map((p,i)=><p key={i}>{p}</p>)}</div></div></div>}
function Facet({facet,go,found,setFound}){const [reader,setReader]=useState(null);const relevant=facet.docs.map(id=>docs.find(d=>d.id===id));const clueFound=found.includes(facet.id);function reveal(){setFound(x=>x.includes(facet.id)?x:[...x,facet.id])}return <main className={`facet-page ${facet.tone} world-${facet.id}`}><ScenePortal facet={facet} onClue={reveal} clueFound={clueFound}/><header className="facet-hero"><div><p className="eyebrow">{facet.kicker}</p><h1>{facet.title}</h1><p>{facet.intro}</p></div><span className="sigil">{facet.symbol}</span></header><section className="chapter"><div className="chapter-head"><span>Field notes growing in this world</span><em>Touch a scroll for the complete original text</em></div><div className="scrolls">{relevant.map(d=><button key={d.id} onClick={()=>setReader(d)}><span>{String(d.id).padStart(2,'0')}</span><div><strong>{d.title}</strong><small>{d.text.slice(0,180)}…</small></div><ArrowRight/></button>)}</div></section>{facet.id==='student'&&<section className="constellation-board"><h2>Pin a hope to the sky</h2>{['medicine','biology','art','AI','Assam','impact'].map((x,i)=><button key={x} style={{'--x':`${12+i*14}%`,'--y':`${20+(i%3)*24}%`}}>{x}</button>)}</section>}{facet.id==='artist'&&<section className="gallery"><img src={seedball} loading="lazy" decoding="async" width="1600" height="2474" alt="Udita holding seed-ball experiment materials"/><div className="art-card"><p>Material spellbook</p><h3>Seed balls, agar dresses, pigment and code</h3><span>Hover over the images. They refuse to stay rectangular.</span></div><img src={screen29} loading="lazy" decoding="async" width="1400" height="788" alt="Dark matter and dark energy presentation from Udita’s portfolio"/></section>}{facet.id==='researcher'&&<section className="gallery research-gallery">{[screen41,mit,screen29].map((x,i)=><img src={x} key={i} loading="lazy" decoding="async" width="1400" height="788" alt={["Neural network research diagram","Conversation with an MIT scientist","Dark matter research presentation"][i]}/>)}</section>}{facet.id==='builder'&&<section className="stats"><div><b>78</b><span>specialized SugarCode modules</span></div><div><b>20+</b><span>global repositories in its planned stack</span></div><div><b>4</b><span>BioNet research directions</span></div></section>}{facet.id==='writer'&&<blockquote>“I had mistaken control for understanding.”<cite>Better questions • hover and listen</cite></blockquote>}{facet.id==='heritage'&&<section className="yelon"><div className="pixel">♛</div><div><p className="eyebrow">Yelon • “good life”</p><h3>A screen-buddy who keeps a language awake</h3><p>Each morning, an eight-pixel-tall woman in a gold faa-sin appears beside the clock with one Tai-Ahom word. The screen opens only when the word is typed back.</p><div className="words"><span>mek <small>mother</small></span><span>lung <small>river</small></span></div></div></section>}<section className={`clue-memory ${clueFound?'found':''}`}><span>{clueFound?facet.clue:'The satchel is still waiting.'}</span><small>{clueFound?'A word followed you out of the scene.':'One of the scene’s four objects is warmer than the others.'}</small></section><div className="pager"><button onClick={()=>go(pageOrder[pageOrder.indexOf(facet.id)-1])}><ArrowLeft/> Previous world</button><button onClick={()=>go(pageOrder[pageOrder.indexOf(facet.id)+1])}>Next world <ArrowRight/></button></div>{reader&&<DocReader doc={reader} onClose={()=>setReader(null)}/>}</main>}
function Archive(){const [q,setQ]=useState(''),[reader,setReader]=useState(null),[toast,setToast]=useState('');const tell=t=>{setToast(t);setTimeout(()=>setToast(''),2600)};const hits=useMemo(()=>docs.filter(d=>(d.title+' '+d.text).toLowerCase().includes(q.toLowerCase())),[q]);return <main className="archive"><PetalWeather kind="archive"/><div className="archive-vines"/><SecretObject type="inkpot" label="A restless inkpot" onFind={()=>tell("The ink writes: search for ‘fragility’.")}><span>♜</span></SecretObject><SecretObject type="bookmoth" label="A library moth" onFind={()=>tell("The moth has read all 13 documents. Its favorite word is ‘rewrite’. ")}><span>෴</span></SecretObject><SecretObject type="shelf-key" label="A key between the shelves" onFind={()=>tell("It opens no lock here. Perhaps it unlocks the reader.")}><span>⚿</span></SecretObject><header><p className="eyebrow">Nothing omitted</p><h1>The complete archive</h1><p>Every original document and every item in the submitted portfolio folder is indexed here. Search a phrase or open a full source scroll.</p><label><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search phages, Assam, agar, BioNet…"/></label></header><section className="archive-grid">{hits.map(d=><button onClick={()=>setReader(d)} key={d.id}><span>{String(d.id).padStart(2,'0')}</span><strong>{d.title}</strong><small>{d.kind} • {d.text.split(/\s+/).length.toLocaleString()} words</small></button>)}</section><section className="drive-index"><h2>Portfolio Drive • {drive.length} artifacts</h2><div>{drive.map(f=><a key={f.id} href={f.web_view_link} target="_blank" rel="noreferrer"><span>{f.mime_type.startsWith('image')?'image':f.mime_type.includes('video')?'film':f.mime_type.includes('folder')?'folder':'file'}</span><strong>{f.name}</strong><ArrowRight/></a>)}</div></section>{reader&&<DocReader doc={reader} onClose={()=>setReader(null)}/>}<Toast text={toast}/></main>}
function Finale({found,go}){const done=found.length===6;const [opened,setOpened]=useState(false),[toast,setToast]=useState('');return <main className={`finale ${done?'ready':''} ${opened?'opened':''}`}><PetalWeather kind="finale"/><div className="finale-trees left"/><div className="finale-trees right"/><div className="door"><div className="door-stars">✦ · ✧ · ✦</div><p className="eyebrow">Where all paths meet</p><h1>{done?(opened?'The forest remembers you.':'The last door is awake.'):'The door is listening.'}</h1>{done&&!opened?<><div className="keyhole" onClick={()=>setOpened(true)}><span>✦</span></div><p>Place your six words into the light. Then touch the keyhole.</p><div className="locks">{facets.map(f=><button className="found" key={f.id}>{f.clue}</button>)}</div></>:done&&opened?<><div className="reveal-bloom"><i/><i/><i/><i/><b>THE RIVER<br/>REMEMBERS<br/>WHAT WE CARRY<br/>HOME</b></div><p>The answer was never a password. It is the thread through every part of me: memory moving like water — through code, cells, color, story and language — until what I make becomes a way home.</p><div className="reveal-grid"><span onMouseEnter={()=>setToast('Research moves like water: adapting, connecting, refusing to stay still.')}>river <small>research that moves</small></span><span onMouseEnter={()=>setToast('Language, art and story keep what time tries to erase.')}>remembers <small>heritage kept alive</small></span><span onMouseEnter={()=>setToast('We carry cells, stories, systems and one another.')}>what we carry <small>everything becomes material</small></span><span onMouseEnter={()=>setToast('Home is Assam — and every future built from it.')}>home <small>the root and the return</small></span></div></>:<><p>You have found {found.length} of 6 words. The last door opens only for someone who has touched every world.</p><div className="locks">{facets.map(f=><button key={f.id} className={found.includes(f.id)?'found':''} onClick={()=>go(f.id)}>{found.includes(f.id)?f.clue:'sleeping'}</button>)}</div></>}<button className="primary" onClick={()=>go(done&&opened?'home':facets.find(f=>!found.includes(f.id))?.id||'home')}>{done&&opened?'Begin again':'Follow the warmest path'} <ArrowRight/></button></div><Toast text={toast}/></main>}
function App(){const [page,setPage]=useState(()=>location.hash.slice(1)||'home'),[found,setFound]=useState(()=>new URLSearchParams(location.search).get('all')==='1'?facets.map(f=>f.id):JSON.parse(localStorage.getItem('udita-clues')||'[]'));const go=p=>{setPage(p);location.hash=p;scrollTo({top:0,behavior:'smooth'})};useEffect(()=>{localStorage.setItem('udita-clues',JSON.stringify(found))},[found]);useEffect(()=>{const h=()=>setPage(location.hash.slice(1)||'home');addEventListener('hashchange',h);return()=>removeEventListener('hashchange',h)},[]);const facet=facets.find(f=>f.id===page);return <><a className="skip-link" href="#main-content">Skip to content</a>{page!=='journey'&&<Suspense fallback={<div className="forest forest-fallback"/>}><Journey3D/></Suspense>}<FairyCompanion page={page}/>{page!=='journey'&&<Nav page={page} go={go} found={found}/>}<div id="main-content" tabIndex="-1">{page==='journey'?<Journey go={go} found={found} setFound={setFound}/>:page==='home'?<Home go={go}/>:facet?<Facet facet={facet} go={go} found={found} setFound={setFound}/>:page==='archive'?<Archive/>:<Finale found={found} go={go}/>}</div><footer><span>Udita Phookan</span><span>Made from questions, Assam rain and unreasonable hope.</span></footer></>};createRoot(document.getElementById('root')).render(<ErrorBoundary><App/></ErrorBoundary>);
